  xm8 N009 Vpbias VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm8} l={L_xm8}
  xm9 n2 0 N009 VDD sky130_fd_pr__pfet_01v8 w={W_xm9} l={L_xm9}
  xm10 n2 n2 0 0 sky130_fd_pr__nfet_01v8 w={W_xm10} l={L_xm10}
